/** Stimulus catalogue types. The catalogue itself is generated by tools/stimuli/build.py. */

export type Family = 'recognition' | 'semantic' | 'odd_one_out' | 'functional' | 'absurd';

export type SelectionMode = 'single' | 'multiple';

/**
 * `unambiguous`: one defensible answer set, suitable for scored and, later, confirmatory trials.
 * `entertainment`: scored with an explicit operational definition, but excluded from confirmatory analysis.
 */
export type ResearchClass = 'unambiguous' | 'entertainment';

export interface TileProvenance {
  model: string;
  model_revision: string;
  licence: string;
  prompt: string;
  seed: number;
  steps: number;
  guidance_scale: number;
  generated_at: string;
  edits: string;
}

export interface StimulusTile {
  /** Stable identifier; never written into the page, so it cannot reveal the answer. */
  tile_id: string;
  /** Opaque file names (content hashes) under public/stimuli/. */
  src: string;
  src_small: string;
  width: number;
  height: number;
  /** SHA-256 of the full-size published file. */
  sha256: string;
  /** Human-checked description, used as the image's alternative text. */
  alt: string;
  provenance: TileProvenance;
}

export interface Stimulus {
  stimulus_id: string;
  version: number;
  /** Hash over the grid's instruction, answer key and tile hashes. */
  hash: string;
  family: Family;
  mode: SelectionMode;
  instruction: string;
  /** Alternative phrasings of the same search for the V2 instruction manipulation. */
  instruction_variants: { direct?: string; semantic?: string };
  hint: string;
  operational_definition?: string;
  explanation: string;
  difficulty: 'easy' | 'medium' | 'hard';
  research_class: ResearchClass;
  /** Alternative lines per outcome; one is drawn at random, so repeated grids do not repeat the joke. */
  feedback: { correct: string[]; partial?: string[]; incorrect: string[] };
  tiles: StimulusTile[];
  answer_key: string[];
}

export interface Catalogue {
  schema_version: number;
  catalogue_version: string;
  families: Family[];
  stimuli: Stimulus[];
}
